import json
d = json.load(open('/private/tmp/claude-501/-Users-taha/c7a33960-1c96-4b0c-b15f-02a996414e54/scratchpad/layout2.json'))
content = d['primaryContentSections'][0]['content']
table = content[75]
rows = table['rows']
def cell_text(cell):
    out = []
    for item in cell:
        if item.get('type')=='paragraph':
            for ic in item.get('inlineContent',[]):
                if ic.get('type')=='text':
                    out.append(ic.get('text'))
                elif ic.get('type')=='reference':
                    out.append('[REF:'+ic.get('identifier','')+']')
        elif item.get('type')=='text':
            out.append(item.get('text'))
    return ' '.join(out).strip()

for r in rows:
    print(' | '.join(cell_text(c) for c in r))
